using UnityEngine;
using UnityEngine.InputSystem;

public class PlayerMover : MonoBehaviour
{
    // How fast the player slides, in units a second.
    [SerializeField] private float speed = 8f;

    void Update()
    {
        // 0 means standing still. -1 is left, 1 is right.
        float direction = 0f;

        if (Keyboard.current.aKey.isPressed)
        {
            direction = -1f;
        }

        if (Keyboard.current.dKey.isPressed)
        {
            direction = 1f;
        }

        // Copy the position, change the x part, then put it back.
        Vector3 position = transform.position;
        position.x = position.x + direction * speed * Time.deltaTime;

        // Stop the player at the edges of the floor.
        position.x = Mathf.Clamp(position.x, -9f, 9f);

        transform.position = position;
    }
}

using UnityEngine;

public class HazardSpawner : MonoBehaviour
{
    // The prefab to copy. You drag it in from the Project window.
    [SerializeField] private GameObject hazardPrefab;

    // How far left and right hazards may appear.
    [SerializeField] private float range = 9f;

    // How high above the floor they appear.
    [SerializeField] private float spawnHeight = 11f;

    // Seconds between hazards.
    [SerializeField] private float interval = 1.5f;

    // Counts down to the next spawn.
    private float timer;

    void Start()
    {
        timer = interval;
    }

    void Update()
    {
        // Take away the time since the last frame.
        timer = timer - Time.deltaTime;

        if (timer <= 0f)
        {
            SpawnHazard();
            timer = interval;
        }
    }

    void SpawnHazard()
    {
        // A random number from -9 up to 9.
        float x = Random.Range(-range, range);
        Vector3 position = new Vector3(x, spawnHeight, 0f);

        // Make one copy of the prefab at that position, not turned.
        Instantiate(hazardPrefab, position, Quaternion.identity);
    }
}

using UnityEngine;

public class HazardSpawner : MonoBehaviour
{
    // The prefab to copy. You drag it in from the Project window.
    [SerializeField] private GameObject hazardPrefab;

    // How far left and right hazards may appear.
    [SerializeField] private float range = 9f;

    // How high above the floor they appear.
    [SerializeField] private float spawnHeight = 11f;

    // Seconds between hazards at the start.
    [SerializeField] private float interval = 1.5f;

    // The shortest gap allowed, so the game stays fair.
    [SerializeField] private float minInterval = 0.4f;

    // Each spawn multiplies the gap by this. 0.95 is 5 percent shorter.
    [SerializeField] private float shrink = 0.95f;

    // Seconds a hazard lives before it is destroyed.
    [SerializeField] private float lifetime = 6f;

    // Counts down to the next spawn.
    private float timer;

    void Start()
    {
        timer = interval;
    }

    void Update()
    {
        // Take away the time since the last frame.
        timer = timer - Time.deltaTime;

        if (timer <= 0f)
        {
            SpawnHazard();

            // Make the next gap a little shorter, but never below the minimum.
            interval = Mathf.Max(minInterval, interval * shrink);
            timer = interval;
        }
    }

    void SpawnHazard()
    {
        float x = Random.Range(-range, range);
        Vector3 position = new Vector3(x, spawnHeight, 0f);

        // Keep the new copy in a variable so we can destroy it later.
        GameObject hazard = Instantiate(hazardPrefab, position, Quaternion.identity);

        // Destroy this copy after lifetime seconds.
        Destroy(hazard, lifetime);
    }
}

