using UnityEngine.SceneManagement;

public class GameManager : MonoBehaviour
{
    // The text that shows the lives. You drag it in from the Hierarchy.
    [SerializeField] private TMP_Text livesText;

    // The panel with Game over and the Restart button.
    [SerializeField] private GameObject gameOverPanel;

    // How many lives the player starts with.
    [SerializeField] private int lives = 3;

    // Game state: is the game over right now?
    private bool isGameOver = false;

    void Start()
    {
        // Make sure game time runs at normal speed.
        Time.timeScale = 1f;

        // Hide the game over panel until it is needed.
        gameOverPanel.SetActive(false);

        UpdateLivesText();
    }

    // Other scripts call this when the player is hit.
    public void LoseLife()
    {
        // Do nothing if the game has already ended.
        if (isGameOver)
        {
            return;
        }

        lives = lives - 1;
        UpdateLivesText();

        if (lives <= 0)
        {
            GameOver();
        }
    }

    private void GameOver()
    {
        isGameOver = true;
        gameOverPanel.SetActive(true);

        // Freeze game time: hazards stop and the spawner stops.
        Time.timeScale = 0f;
    }

    // The Restart button calls this.
    public void Restart()
    {
        // Put game time back to normal before the scene reloads.
        Time.timeScale = 1f;

        // Rebuild the scene that is open now.
        SceneManager.LoadScene(SceneManager.GetActiveScene().name);
    }

    private void UpdateLivesText()
    {
        livesText.text = "Lives: " + lives;
    }
}

using UnityEngine;

public class HazardHit : MonoBehaviour
{
    // The GameManager that keeps the lives.
    private GameManager gameManager;

    void Start()
    {
        // A prefab cannot hold an object from the scene, so each copy finds it.
        gameManager = FindAnyObjectByType<GameManager>();
    }

    // Unity calls this when this object touches another solid object.
    void OnCollisionEnter(Collision collision)
    {
        // Only react to the Player, not to the floor.
        if (collision.gameObject.CompareTag("Player"))
        {
            gameManager.LoseLife();

            // Remove this hazard so it cannot hit twice.
            Destroy(gameObject);
        }
    }
}

using UnityEngine;

// Plays sound effects for Dodge. Other scripts call PlayHit and PlayGameOver.
public class SoundPlayer : MonoBehaviour
{
    // The Audio Source that does the playing (on this same object)
    [SerializeField] private AudioSource source;

    // The sound files to play
    [SerializeField] private AudioClip hitClip;
    [SerializeField] private AudioClip gameOverClip;

    // How loud the effects are, from 0 (silent) to 1 (full)
    [SerializeField] private float volume = 0.8f;

    // How far the pitch can wander up or down on each play
    [SerializeField] private float pitchVariation = 0.1f;

    // Public so that other scripts can call it
    public void PlayHit()
    {
        PlayClip(hitClip);
    }

    public void PlayGameOver()
    {
        PlayClip(gameOverClip);
    }

    // Private: only this script uses it
    private void PlayClip(AudioClip clip)
    {
        // Pick a pitch a little above or below 1 (normal speed)
        source.pitch = 1f + Random.Range(-pitchVariation, pitchVariation);

        // Play the clip on top of anything already playing
        source.PlayOneShot(clip, volume);
    }
}

using UnityEngine;

// Attached to each hazard. When it touches the Player it takes a life,
// shows a burst where it hit, and removes itself.
public class HazardHit : MonoBehaviour
{
    // The burst to create on a hit (drag the HitBurst prefab here)
    [SerializeField] private GameObject burstPrefab;

    private void OnTriggerEnter(Collider other)
    {
        // Only the Player counts; the floor and other hazards do not
        if (other.CompareTag("Player"))
        {
            // Take a life (this also plays the hit sound)
            FindAnyObjectByType<GameManager>().LoseLife();

            // Make a copy of the burst where this hazard is, with no rotation
            Instantiate(burstPrefab, transform.position, Quaternion.identity);

            // Remove the hazard
            Destroy(gameObject);
        }
    }
}
